import io.jsonwebtoken.*;
import java.util.Date;

public class JwtUtil {
    private static final String SECRET = "mySecretKey12345";
    private static final long EXPIRY_MS = 3600000; // 1 hour

    public String generateToken(String username) {
        return Jwts.builder()
                .setSubject(username)              // payload: who this token is for
                .setIssuedAt(new Date())           // payload: when issued
                .setExpiration(new Date(System.currentTimeMillis() + EXPIRY_MS))
                .signWith(SignatureAlgorithm.HS256, SECRET)  // creates signature
                .compact();                        // returns Header.Payload.Signature
    }

    public String extractUsername(String token) {
        return Jwts.parser()
                .setSigningKey(SECRET)             // verifies signature first
                .parseClaimsJws(token)
                .getBody()
                .getSubject();                     // extracts username from payload
    }
}

@Component
public class JwtAuthenticationFilter extends OncePerRequestFilter {
    @Autowired private JwtUtil jwtUtil;
    @Autowired private UserDetailsService userDetailsService;

    @Override
    protected void doFilterInternal(HttpServletRequest request,
                                    HttpServletResponse response,
                                    FilterChain chain) throws ServletException, IOException {
        String authHeader = request.getHeader("Authorization");
        if (authHeader != null && authHeader.startsWith("Bearer ")) {
            String token = authHeader.substring(7);          // strip "Bearer "
            String username = jwtUtil.extractUsername(token); // validate + extract

            if (username != null && SecurityContextHolder.getContext().getAuthentication() == null) {
                UserDetails userDetails = userDetailsService.loadUserByUsername(username);
                var authToken = new UsernamePasswordAuthenticationToken(
                        userDetails, null, userDetails.getAuthorities());
                SecurityContextHolder.getContext().setAuthentication(authToken); // set context
            }
        }
        chain.doFilter(request, response);  // continue to controller
    }
}

import io.jsonwebtoken.*;
import io.jsonwebtoken.security.SignatureException;

public class SecureJwtValidator {
    private static final String SECRET = System.getenv("JWT_SECRET"); // never hardcode
    private static final SignatureAlgorithm EXPECTED_ALG = SignatureAlgorithm.HS256;

    public Claims validateToken(String token) {
        try {
            var parser = Jwts.parserBuilder()
                    .setSigningKey(SECRET)
                    .requireAlgorithm(EXPECTED_ALG.getValue())  // reject alg:none
                    .build();
            var jwt = parser.parseClaimsJws(token);

            // Explicit algorithm check (defense in depth)
            if (!EXPECTED_ALG.getValue().equals(jwt.getHeader().getAlgorithm())) {
                throw new JwtException("Invalid algorithm");
            }
            return jwt.getBody();
        } catch (ExpiredJwtException e) {
            throw new SecurityException("Token expired", e);
        } catch (SignatureException e) {
            throw new SecurityException("Invalid signature", e);  // tampered token
        }
    }
}

@RestController
@RequestMapping("/auth")
public class AuthController {
    @Autowired private JwtUtil jwtUtil;
    @Autowired private RefreshTokenService refreshTokenService;

    @PostMapping("/login")
    public LoginResponse login(@RequestBody LoginRequest request) {
        // validate credentials (simplified)
        var accessToken = jwtUtil.generateAccessToken(request.username(), 15); // 15 min
        var refreshToken = refreshTokenService.createRefreshToken(request.username());
        return new LoginResponse(accessToken, refreshToken.getToken());
    }

    @PostMapping("/refresh")
    public TokenResponse refresh(@RequestBody RefreshRequest request) {
        var storedToken = refreshTokenService.findByToken(request.refreshToken())
                .orElseThrow(() -> new SecurityException("Invalid refresh token"));

        if (storedToken.isExpired()) {
            throw new SecurityException("Refresh token expired");
        }

        refreshTokenService.rotateToken(storedToken);  // invalidate old, create new
        var newAccessToken = jwtUtil.generateAccessToken(storedToken.getUsername(), 15);
        return new TokenResponse(newAccessToken, storedToken.getToken());
    }
}
